/**
 * The TypeScript mirror of `app/schemas/` and `app/models/enums.py`.
 *
 * `docs/CONTRACTS.md` §18 makes this file binding: **enum string values must match the
 * Python character-for-character.** A drift here does not fail loudly — it produces a filter
 * that matches nothing, a badge with no colour, and a screen that renders empty while the
 * network tab shows a 200. Every value below was generated by reading `app/models/enums.py`
 * and the live OpenAPI document served by `app.main:app`, not from memory.
 *
 * Two conventions, applied throughout:
 *
 * **Enums are ordered tuples, not TypeScript `enum`s.** `const X = [...] as const` plus
 * `type X = (typeof X)[number]` gives the union type *and* a runtime list in declaration
 * order — which is what a filter dropdown, a legend, and a status-group header all need.
 * A TypeScript `enum` gives neither, and `isolatedModules` makes `const enum` unusable.
 *
 * **Optionality mirrors pydantic, not convenience.** A field the server always sends is
 * required here; a field with a default is `?`; a field typed `X | None` is `X | null`.
 * `noUncheckedIndexedAccess` plus honest optionality is what catches "the API stopped
 * sending `score`" at compile time in the one place it can still be cheap to fix.
 */

/** ISO-8601 timestamp with timezone, e.g. `2026-08-08T09:41:02.113471+00:00`. */
export type IsoDateTime = string;

/** ISO-8601 calendar date, e.g. `2026-08-08`. */
export type IsoDate = string;

/** A UUID rendered as a string. Every id in this API is one. */
export type Uuid = string;

/** Free-form JSON object, as produced by a pydantic `dict[str, Any]` field. */
export type JsonObject = Record<string, unknown>;

/**
 * Bumped on **any** DTO shape change in this file.
 *
 * It is half of the persisted-cache buster (`docs/UI.md` §10.5): a restored cache entry
 * written by a build whose `ApplicationRead` had different fields is not merely stale, it is
 * wrong, and rendering it produces `undefined` in places the types promise are populated.
 * The other half is `__APP_VERSION__`.
 */
export const API_SCHEMA_VERSION = 1;

/** Prefix every REST route in this file carries. `/health`, `/ready`, `/metrics` and `/ws` do not. */
export const API_PREFIX = '/api/v1';

/** Fixed page size (`DEFAULT_PAGE_LIMIT` in `app/schemas/common.py`). */
export const PAGE_LIMIT = 50;

/** Server-side ceiling on `limit` (`MAX_PAGE_LIMIT`). */
export const MAX_PAGE_LIMIT = 200;

