/** The return shape of every list endpoint. */
export interface Page<T> {
  items: T[];
  total: number;
  limit: number;
  offset: number;
  /** Derived server-side from `offset + items.length < total`, so a short final page is correct. */
  has_more: boolean;
}

/** The single error body every failing endpoint returns. Clients branch on `error`, never `detail`. */
export interface ErrorResponse {
  /** Stable machine-readable code — see {@link API_ERROR_CODES}. */
  error: string;
  detail?: string | null;
  /** Turns a screenshot of an error toast into a log query. */
  correlation_id?: string | null;
}

/** Acknowledgement returned by endpoints whose only answer is "done". */
export interface OkResponse {
  ok: boolean;
  message?: string | null;
  data: JsonObject;
}

/**
 * Stable machine codes from `app/api/errors.py`. Part of the published contract.
 *
 * Not exhaustive as a *type* — a newer backend may add one — which is why callers switch
 * with a default branch rather than relying on exhaustiveness.
 */
export const API_ERROR_CODES = [
  'not_found',
  'invalid_request',
  'validation_error',
  'conflict',
  'internal_error',
  'provider_error',
  'provider_auth_required',
  'rate_limited',
  'posting_unavailable',
  'unsupported_flow',
  'document_render_failed',
  'plugin_not_found',
  'plugin_disabled',
  'plugin_failed',
] as const;
export type ApiErrorCode = (typeof API_ERROR_CODES)[number] | (string & {});

