/** A form field the automation refused to answer rather than guess at. */
export interface ReviewField {
  selector: string;
  label: string;
  kind: FieldKind;
  required: boolean;
  options: string[];
  max_length?: number | null;
  hint?: string | null;
  /** Present but below the confidence floor. Never pre-filled without showing its confidence. */
  suggested_answer?: string | null;
  confidence?: number | null;
}

/** One entry in the human review queue. */
export interface ReviewItem {
  application: ApplicationRead;
  reason?: ReviewReason | null;
  unanswered_fields: ReviewField[];
  payload: JsonObject;
}

/** Body of `POST /reviews/{id}/resolve` — a human's answers, keyed by field selector. */
export interface ReviewResolve {
  answers: JsonObject;
}

/** Body of `POST /reviews/{id}/dismiss`. */
export interface ReviewDismiss {
  note?: string | null;
}

