/** Offset/limit pagination, accepted by every list endpoint. */
export interface PageParams {
  limit?: number;
  offset?: number;
}

/**
 * Filters accepted by `GET /applications` and `GET /reviews` (identical signatures).
 *
 * Every field is optional and nullable-free on purpose: `undefined` means "not filtering",
 * and `normalizeFilters` in `lib/query/keys.ts` strips it before the key is hashed. Adding a
 * `| null` here would reintroduce exactly the cache fragmentation §10.4 warns about.
 */
export interface ApplicationFilters extends PageParams {
  q?: string;
  status?: ApplicationStatus;
  provider?: ATSProviderName;
  company?: string;
  session_id?: Uuid;
  review_reason?: ReviewReason;
  needs_review?: boolean;
  since?: IsoDateTime;
  until?: IsoDateTime;
}

/** Filters accepted by `GET /postings`. */
export interface PostingFilters extends PageParams {
  q?: string;
  provider?: ATSProviderName;
  status?: PostingStatus;
  min_score?: number;
  company?: string;
  since?: IsoDateTime;
  remote_only?: boolean;
}

/** Filters accepted by `GET /knowledge/facts`. */
export interface FactFilters extends PageParams {
  q?: string;
  kind?: FactKind;
  organization?: string;
  role?: string;
  skill?: string;
  active?: boolean;
  verified?: boolean;
  min_impact?: number;
  min_confidence?: number;
}

/** Filters accepted by `GET /knowledge/entities`. */
export interface EntityFilters extends PageParams {
  kind?: EntityKind;
}

/** Filters accepted by `GET /knowledge/graph`. */
export interface GraphFilters {
  /** Comma-joined {@link EntityKind} values; the client joins, the server splits. */
  kinds?: string;
  limit?: number;
}

/** Filters accepted by `GET /logs` (historical search only — the live tail is a ring buffer). */
export interface LogFilters extends PageParams {
  level?: string;
  event?: string;
  correlation_id?: string;
  session_id?: Uuid;
  application_id?: Uuid;
  since?: IsoDateTime;
}

/** Filters accepted by `GET /tracking/signals`. */
export interface SignalFilters extends PageParams {
  source?: SignalSource;
  kind?: SignalKind;
  application_id?: Uuid;
  applied?: boolean;
  needs_review?: boolean;
  since?: IsoDateTime;
  until?: IsoDateTime;
}

/** Filters accepted by `GET /settings/plugins`. */
export interface PluginFilters {
  kind?: PluginKind;
  /** Probing costs one live call per plugin; off by default. */
  probe?: boolean;
}

// ══════════════════════════════════════════════════════════════════════════════════════
// Event stream — GET /ws (docs/CONTRACTS.md §14 and §17.7)
// ══════════════════════════════════════════════════════════════════════════════════════

/**
 * Every event name the bus may publish. Closed by contract (`EVENT_NAMES` in
 * `app/api/events.py`): publishing an unlisted name is refused server-side, so a `default`
 * branch in the client handles only future versions, never a typo.
 */
export const EVENT_NAMES = [
  'session.started',
  'session.updated',
  'session.finished',
  'posting.discovered',
  'posting.scored',
  'application.created',
  'application.status_changed',
  'application.submitted',
  'application.needs_review',
  'knowledge.index_started',
  'knowledge.index_progress',
  'knowledge.index_finished',
  'tracking.sync_started',
  'tracking.sync_progress',
  'tracking.signal_found',
  'tracking.status_changed',
  'tracking.sync_finished',
  'log.entry',
] as const;
export type EventName = (typeof EVENT_NAMES)[number];

/** One broadcast frame, as rendered by `Event.to_wire()`. */
export interface EventFrame<N extends EventName = EventName, P = unknown> {
  event: N;
  payload: P;
  /** Monotonic per-process counter. A gap means the client fell behind and was trimmed. */
  sequence: number;
  at: IsoDateTime;
}

/** Payload of `posting.discovered` — `DiscoveryReport.as_dict()` plus run context. */
export interface DiscoveryReportPayload {
  found: number;
  created: number;
  deduped: number;
  scored: number;
  skipped: number;
  errors: string[];
  by_provider: Record<string, number>;
  /**
   * Boards each provider was asked to poll. Pair it with `by_provider` to tell "nowhere to
   * look" apart from "looked everywhere and found nothing" — a bare `0` reads the same in
   * both cases.
   */
  boards_by_provider: Record<string, number>;
  /** Providers that answered without error and produced nothing. */
  empty_providers: string[];
  duration_seconds: number;
  provider?: string;
  user_id?: Uuid;
  queued_for_apply?: number;
}

/** Payload of `knowledge.index_started`. Carries whichever scope the run has. */
export interface KnowledgeIndexStartedPayload {
  source_id?: Uuid;
  user_id?: Uuid;
  force: boolean;
}

/** Payload of `knowledge.index_progress`. */
export interface KnowledgeIndexProgressPayload {
  source_id?: Uuid;
  user_id?: Uuid;
  /** 0–1 when the total is known; absent when it is not (use an IndeterminateBar then). */
  progress?: number;
  documents?: number;
  chunks?: number;
}

/**
 * Payload of `knowledge.index_finished` — a single {@link IndexReport} for one source, or
 * the folded summary when a whole user was re-indexed.
 */
export type KnowledgeIndexFinishedPayload =
  | IndexReport
  | {
      sources: number;
      skipped: number;
      failed: number;
      documents: number;
      chunks: number;
      facts: number;
      reports: IndexReport[];
      user_id?: Uuid;
    };

/** Payload of `tracking.sync_started`. */
export interface TrackingSyncStartedPayload {
  account_id: Uuid;
  provider: string;
}

/** Payload of `tracking.sync_progress` and `tracking.sync_finished` — `SyncReport.as_dict()`. */
export interface TrackingSyncReportPayload {
  account_id?: Uuid | null;
  fetched: number;
  classified: number;
  matched: number;
  applied: number;
  needs_review: number;
  skipped: number;
  duration_seconds: number;
  errors: string[];
}

/** Payload of `tracking.signal_found`. */
export interface TrackingSignalFoundPayload {
  id: Uuid;
  kind: SignalKind;
  application_id?: Uuid | null;
  confidence: number;
}

/** Payload of `tracking.status_changed`. */
export interface TrackingStatusChangedPayload {
  application_id: Uuid;
  status: ApplicationStatus;
  source: StatusSource;
  confidence: number;
  signal_id: Uuid;
}

/**
 * The discriminated union of every frame the client may receive.
 *
 * The entity-carrying members are what make `setQueryData` possible without a refetch: the
 * payload is byte-for-byte what the corresponding REST endpoint returns. The rest are
 * payload-less in the §10.8 sense — they carry counters, not entities, and are handled by a
 * narrow `invalidateQueries`.
 */
export type AppEvent =
  | EventFrame<'session.started', SessionRead>
  | EventFrame<'session.updated', SessionRead>
  | EventFrame<'session.finished', SessionRead>
  | EventFrame<'posting.discovered', DiscoveryReportPayload>
  | EventFrame<'posting.scored', ScoreRead>
  | EventFrame<'application.created', ApplicationRead>
  | EventFrame<'application.status_changed', ApplicationRead>
  | EventFrame<'application.submitted', ApplicationRead>
  | EventFrame<'application.needs_review', ApplicationRead>
  | EventFrame<'knowledge.index_started', KnowledgeIndexStartedPayload>
  | EventFrame<'knowledge.index_progress', KnowledgeIndexProgressPayload>
  | EventFrame<'knowledge.index_finished', KnowledgeIndexFinishedPayload>
  | EventFrame<'tracking.sync_started', TrackingSyncStartedPayload>
  | EventFrame<'tracking.sync_progress', TrackingSyncReportPayload>
  | EventFrame<'tracking.signal_found', TrackingSignalFoundPayload>
  | EventFrame<'tracking.status_changed', TrackingStatusChangedPayload>
  | EventFrame<'tracking.sync_finished', TrackingSyncReportPayload>
  | EventFrame<'log.entry', LogEntryRead>;

/** The subset of {@link AppEvent} whose payload is an `ApplicationRead`. */
export type ApplicationEventName = Extract<AppEvent, { payload: ApplicationRead }>['event'];

/** The subset of {@link AppEvent} whose payload is a `SessionRead`. */
export type SessionEventName = Extract<AppEvent, { payload: SessionRead }>['event'];
